1	"use client";
2	
3	import React, { useEffect, useRef, useState } from 'react';
4	import { Sidebar } from '@/components/Sidebar';
5	import { FileSidebar } from '@/components/FileSidebar';
6	import { SliceSidebar } from '@/components/SliceSidebar';
7	import { CategoriesSidebar } from '@/components/CategoriesSidebar';
8	import { PrinterConfigSidebar } from '@/components/PrinterConfigSidebar';
9	import { AxisSidebar } from '@/components/AxisSidebar';
10	import { ModelingSidebar } from '@/components/ModelingSidebar';
11	import { TopRightMenu } from '@/components/TopRightMenu';
12	import { ModelStatusBox } from '@/components/ModelStatusBox';
13	import { ModelHoverTooltip } from '@/components/ModelHoverTooltip';
14	import { TextureEditorModal } from '@/components/TextureEditorModal';
15	import { SliceModal } from '@/components/SliceModal';
16	import { SlicingProgressModal } from '@/components/SlicingProgressModal';
17	import { ViewCube } from '@/components/ViewCube';
18	import { Viewport3D } from '@/components/Viewport3D';
19	import { SpaceTransitionOverlay } from '@/components/SpaceTransitionOverlay';
20	import { GCodePreview } from '@/components/GCodePreview';
21	import { GCodePreviewBar } from '@/components/GCodePreviewBar';
22	import { GCodeSpeedSelector } from '@/components/GCodeSpeedSelector';
23	import { GCodeLineTypeLegend } from '@/components/GCodeLineTypeLegend';
24	import { GCodeInfoPanel } from '@/components/GCodeInfoPanel';
25	import { GCodeConversionCard } from '@/components/GCodeConversionCard';
26	import { useGCodePreview } from '@/hooks/use-gcode-preview';
27	import { useAnimate } from 'framer-motion';
28	import { Box } from 'lucide-react';
29	import { showSuccess } from '@/utils/toast';
30	
31	interface ModelStatus {
32	  name: string;
33	  dimensions: { x: number; y: number; z: number } | null;
34	}
35	
36	const Index = () => {
37	  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer'>('3d-view');
38	  const [activeCategory, setActiveCategory] = useState<string | null>(null);
39	  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
40	  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
41	  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
42	  const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
43	  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
44	  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
45	  const [isPreviewActive, setIsPreviewActive] = useState(false);
46	  const isPreviewActiveRef = useRef(isPreviewActive);
47	  isPreviewActiveRef.current = isPreviewActive;
48	  // Logique de l'espace Prévisualisation (chargement/lecture G-code) : appelée ici (et non dans
49	  // GCodePreview) car sa barre de lecture (GCodePreviewBar) partage la rangée du bas avec la
50	  // pastille de statut du plateau, ce qui demande que les deux soient des enfants directs du même
51	  // conteneur flex plutôt que des composants positionnés indépendamment.
52	  const gcodePreview = useGCodePreview(isPreviewActive);
53	  // Le temps que ModelingSidebar déforme sa propre silhouette entre la forme de la pilule/des deux
54	  // panneaux de Prévisualisation et sa forme normale — cf. le commentaire sur `onTabChange` plus
55	  // bas et le prop `morph` de ModelingSidebar. `null` = pas de morph en cours ; sinon, `direction`
56	  // indique le sens ('enter' : la pilule/Prévisualisation devient le panneau Modélisation, 'exit' :
57	  // l'inverse) et `fromPreview` l'état de Prévisualisation à l'autre bout du morph (pilule ou
58	  // panneaux Preview) — figé à l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis
59	  // isPreviewActive : Sidebar mute ce dernier dans le même geste, avant qu'on ait la chance de lire
60	  // sa valeur de départ. Contrairement à l'ancienne approche (deux calques à synchroniser — un
61	  // verre animé séparé, puis le vrai panneau), c'est ICI le même élément, déjà affiché avec son
62	  // contenu réel, qui change de forme : plus de raccord entre deux éléments distincts, donc plus
63	  // de risque de clignotement à la jonction.
64	  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
65	  // Vrai dès le CLIC vers Modélisation (cf. l'écouteur d'apex-entering-modeling plus bas), jamais
66	  // seulement à `onCovered` (~900ms plus tard, une fois le rideau refermé) : le fondu-glissement du
67	  // panneau du bas de Prévisualisation doit être visible EN TRANSPARENCE À TRAVERS le rideau qui
68	  // monte, pas caché derrière lui — contrairement au vrai changement d'onglet (`onTabChange`), qui
69	  // lui reste cadencé par `onCovered`. Redevient faux une fois le morph 'enter' effectivement lancé
70	  // (le panneau du bas a alors largement eu le temps de finir sa disparition, 260ms contre les
71	  // ~900ms d'attente du rideau).
72	  const [leavingToModeling, setLeavingToModeling] = useState(false);
73	  const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
74	  const prevPreviewActiveRef = useRef(isPreviewActive);
75	
76	  // Au changement d'espace, la barre d'aide (TopRightMenu) passe par le coin bas gauche, là où
77	  // se trouve la barre de statut : celle-ci se rentre sous le bord de l'écran juste avant
78	  // (0,2 → 0,45 s ; la barre d'aide démarre à 0,495 s) et ressort une fois la barre d'aide
79	  // arrivée (1,1 s), pour ne pas se faire recouvrir.
80	  useEffect(() => {
81	    if (prevPreviewActiveRef.current === isPreviewActive) return;
82	    prevPreviewActiveRef.current = isPreviewActive;
83	    if (!statusBarRef.current) return;
84	    animateStatusBar(
85	      statusBarRef.current,
86	      { y: [0, 0, 80, 80, 0] },
87	      { duration: 1.4, times: [0, 0.2 / 1.4, 0.45 / 1.4, 1.1 / 1.4, 1], ease: [0.25, 1, 0.5, 1] },
88	    );
89	  }, [isPreviewActive, animateStatusBar, statusBarRef]);
90	
91	  /** L'onglet « Modélisation » de la Sidebar porte la valeur 'settings'. */
92	  const isModeling = activeTab === 'settings';
93	
94	  // Une fois CategoriesSidebar (et son panneau du bas) effectivement démontée par le passage en
95	  // Modélisation, `leavingToModeling` peut redescendre : il n'a plus d'effet visuel à cet instant
96	  // (le fondu est terminé depuis longtemps), mais doit être prêt (`false`) pour un futur cycle.
97	  useEffect(() => {
98	    if (isModeling) setLeavingToModeling(false);
99	  }, [isModeling]);
100	
101	  // Vrai du début d'un morph de sortie de Modélisation jusqu'au commit qui le termine, où
102	  // CategoriesSidebar est remontée et le lit (une seule fois, à son montage). Remis à `false` juste
103	  // après, une fois ce montage passé.
104	  const [arrivingFromModeling, setArrivingFromModeling] = useState(false);
105	  useEffect(() => {
106	    if (!modelingMorph) setArrivingFromModeling(false);
107	  }, [modelingMorph]);
108	
109	  React.useEffect(() => {
110	    const handleModelSelected = (event: CustomEvent<{
111	      name: string | null;
112	      dimensions?: { x: number; y: number; z: number };
113	    }>) => {
114	      if (!event.detail?.name) {
115	        setModelStatus(null);
116	        return;
117	      }
118	
119	      setModelStatus({
120	        name: event.detail.name,
121	        dimensions: event.detail.dimensions ?? null,
122	      });
123	    };
124	
125	    const handleModelImported = (event: CustomEvent<File>) => {
126	      if (event.detail?.name) {
127	        setModelStatus({ name: event.detail.name, dimensions: null });
128	      }
129	    };
130	
131	    const handlePreviewToggled = (event: CustomEvent<{ active: boolean }>) => {
132	      setIsPreviewActive(!!event.detail?.active);
133	    };
134	
135	    // Dispatché par Sidebar.tsx (handleTopTabClick) au tout début du clic vers Modélisation, avant
136	    // même que le rideau plein écran ne commence à monter — cf. le commentaire sur
137	    // `leavingToModeling` plus haut.
138	    const handleEnteringModeling = () => setLeavingToModeling(true);
139	
140	    window.addEventListener('apex-mesh-selected', handleModelSelected as EventListener);
141	    window.addEventListener('apex-import-model', handleModelImported as EventListener);
142	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
143	    window.addEventListener('apex-entering-modeling', handleEnteringModeling);
144	
145	    return () => {
146	      window.removeEventListener('apex-mesh-selected', handleModelSelected as EventListener);
147	      window.removeEventListener('apex-import-model', handleModelImported as EventListener);
148	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
149	      window.removeEventListener('apex-entering-modeling', handleEnteringModeling);
150	    };
151	  }, []);
152	
153	  const handleSlice = () => {
154	    window.dispatchEvent(new CustomEvent('apex-request-slice-models'));
155	    setIsSliceModalOpen(true);
156	  };
157	
158	  const handleConfirmSlice = () => {
159	    window.dispatchEvent(new CustomEvent('apex-slice-all-models'));
160	    setIsSliceModalOpen(false);
161	    setIsSlicingProgressOpen(true);
162	  };
163	
164	  const handleSlicingFinished = () => {
165	    setIsSlicingProgressOpen(false);
166	    showSuccess("Slicing plate completed successfully!");
167	  };
168	
169	  const handleOpenModel = () => {
170	    showSuccess("Select an STL or GLB file to add a model.");
171	  };
172	
173	  const handleSaveProject = () => {
174	    showSuccess("Project saved successfully.");
175	  };
176	
177	  return (
178	    <div
179	      className="flex flex-col h-screen w-screen overflow-hidden select-none relative"
180	      style={{ backgroundColor: '#2a2d34' }}
181	    >
182	      <FileSidebar 
183	        onOpenModel={handleOpenModel}
184	        onSaveProject={handleSaveProject}
185	        onOpenSettings={() => setActiveTab('settings')}
186	        onOpenPrinterConfig={() => {
187	          setIsPrinterConfigOpen(!isPrinterConfigOpen);
188	          setActiveCategory(null);
189	        }}
190	        selectedPrinter={selectedPrinter}
191	        selectedFilament={selectedFilament}
192	      />
193	
194	      <ModelStatusBox />
195	      <ModelHoverTooltip />
196	      <TextureEditorModal />
197	      <SliceModal
198	        isOpen={isSliceModalOpen}
199	        onClose={() => setIsSliceModalOpen(false)}
200	        onConfirm={handleConfirmSlice}
201	      />
202	      <SlicingProgressModal
203	        isOpen={isSlicingProgressOpen}
204	        onClose={() => setIsSlicingProgressOpen(false)}
205	        onFinished={handleSlicingFinished}
206	      />
207	
208	      <Sidebar
209	        activeTab={activeTab}
210	        onTabChange={(tab, toPreview) => {
211	          // Passage vers ou hors de Modélisation : le rideau plein écran (déjà déclenché par
212	          // Sidebar avant cet appel, cf. playSpaceTransition) masque le changement de `main`,
213	          // pendant lequel ModelingSidebar (montée en permanence tant que isModeling ||
214	          // modelingMorph) joue le morph — cf. son prop `morph`.
215	          if (tab === 'settings' && !isModeling) {
216	            // L'état de départ (Préparation ou Prévisualisation) est lu MAINTENANT depuis
217	            // isPreviewActiveRef, avant que Sidebar ne le fasse passer à jour dans ce même geste.
218	            // Les éléments sans place en Modélisation ont déjà disparu depuis le clic
219	            // (apex-entering-modeling, ~900ms plus tôt) : la déformation peut commencer tout de
220	            // suite, dans le même commit que la bascule CategoriesSidebar → ModelingSidebar.
221	            setModelingMorph({ direction: 'enter', fromPreview: isPreviewActiveRef.current });
222	          } else if (tab !== 'settings' && isModeling) {
223	            // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
224	            // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui
225	            // passe `toPreview: true`) — la destination ne peut donc pas se lire depuis `tab` seul.
226	            setModelingMorph({ direction: 'exit', fromPreview: !!toPreview });
227	            setArrivingFromModeling(true);
228	          }
229	          setActiveTab(tab === 'box' ? '3d-view' : tab);
230	          setIsPrinterConfigOpen(false);
231	        }}
232	        onOpenModel={handleOpenModel}
233	      />
234	
235	      <TopRightMenu />
236	      <AxisSidebar />
237	      <ViewCube />
238	
239	      {/* Les panneaux slicer et le panneau modélisation s'excluent mutuellement. La bascule se fait
240	          TOUJOURS dans un seul commit, par un rendu conditionnel simple — jamais via
241	          AnimatePresence, qui retarde le démontage de l'ancien côté (et en mode 'wait', le
242	          montage du nouveau) d'au moins une tâche, donc d'au moins une frame peinte. Toute
243	          l'animation visible est portée ailleurs : la déformation par ModelingSidebar (prop
244	          `morph`), les fondus par `animate` dès le clic. */}
245	      {isModeling || modelingMorph?.direction === 'exit' ? (
246	        <ModelingSidebar
247	          morph={
248	            modelingMorph
249	              ? { ...modelingMorph, onDone: () => setModelingMorph(null) }
250	              : undefined
251	          }
252	        />
253	      ) : (
254	          <>
255	            <CategoriesSidebar
256	              activeCategory={activeCategory}
257	              onSelectCategory={(cat) => {
258	                setActiveCategory(cat);
259	                if (cat) setIsPrinterConfigOpen(false);
260	              }}
261	              // Remonté à la fin d'un morph de sortie de Modélisation : ce composant doit apparaître
262	              // directement dans la forme que ModelingSidebar vient de prendre (pilule ou panneaux
263	              // de Prévisualisation), sans rejouer d'entrée ni de mitose. Ces deux props ne sont lues
264	              // qu'au montage (figées en interne).
265	              initialPreviewActive={isPreviewActive}
266	              arrivingFromModeling={arrivingFromModeling}
267	              leavingToModeling={leavingToModeling}
268	              previewUpperContent={
269	                <GCodeLineTypeLegend
270	                  fileInfo={gcodePreview.fileInfo}
271	                  visibility={gcodePreview.lineVisibility}
272	                  onToggle={gcodePreview.setLineVisible}
273	                />
274	              }
275	              previewLowerHeader={<GCodeInfoPanel fileInfo={gcodePreview.fileInfo} />}
276	              previewBelowContent={
277	                <GCodeConversionCard
278	                  source={gcodePreview.conversionSource}
279	                  conversion={gcodePreview.conversion}
280	                  onConvert={gcodePreview.convert}
281	                  onHighlightOffPlate={gcodePreview.setOffPlateHighlight}
282	                  available={gcodePreview.conversionAvailable}
283	                />
284	              }
285	              previewLowerContent={
286	                <GCodeSpeedSelector
287	                  speed={gcodePreview.speed}
288	                  setSpeed={gcodePreview.setSpeed}
289	                  showFullHead={gcodePreview.showFullHead}
290	                  setShowFullHead={gcodePreview.setShowFullHead}
291	                />
292	              }
293	            />
294	
295	            <PrinterConfigSidebar
296	              isOpen={isPrinterConfigOpen}
297	              onClose={() => setIsPrinterConfigOpen(false)}
298	              selectedPrinter={selectedPrinter}
299	              onSelectPrinter={setSelectedPrinter}
300	              selectedFilament={selectedFilament}
301	              onSelectFilament={setSelectedFilament}
302	            />
303	
304	            <SliceSidebar
305	              onSlice={handleSlice}
306	              previewExport={isPreviewActive ? {
307	                enabled: gcodePreview.canExport,
308	                onExport: gcodePreview.exportGCode,
309	                reason: !gcodePreview.fileInfo
310	                  ? 'Chargez un G-code pour pouvoir l’exporter.'
311	                  : gcodePreview.conversion.status === 'running'
312	                    ? 'Conversion en cours…'
313	                    : "Convertissez d'abord le G-code 3 axes en polaire (carte Conversion, sous les panneaux).",
314	              } : undefined}
315	            />
316	          </>
317	      )}
318	
319	      <main className="flex-1 flex flex-col relative overflow-hidden z-10 bg-transparent">
320	        <div className="flex-1 w-full h-full">
321	          <Viewport3D />
322	        </div>
323	
324	        {/* Espace Prévisualisation : interface du prévisualisateur G-code polaire. Le tracé
325	            lui-même est rendu par Viewport3D, dans la même scène que la Préparation. Toujours
326	            monté pour conserver le fichier chargé d'un aller-retour à l'autre. */}
327	        <GCodePreview active={isPreviewActive} />
328	
329	        {/* À l'intérieur de `main` (donc borné à l'espace 3D) et sous les panneaux `position:
330	            fixed` (sidebars, menus, tooltips, z-index 1000+) : le flou et le voile ne doivent
331	            couvrir que le viewport, jamais les éléments en superposition. */}
332	        <SpaceTransitionOverlay />
333	
334	        {/* Bottom status / stats overlay — au-dessus du rideau de transition (z-index 30) pour
335	            ne pas être flouté, comme les panneaux fixes. Seule la pastille de statut (premier
336	            enfant, animé via statusBarRef) se rentre sous le bord de l'écran au changement
337	            d'espace : c'est elle qui se trouve dans le coin bas gauche où la barre d'aide vient se
338	            poser en Prévisualisation (cf. TopRightMenu). GCodePreviewBar, à droite, a sa PROPRE
339	            animation d'entrée/sortie (glissement depuis le bas) et ne doit donc PAS être montée à
340	            l'intérieur du conteneur animé par statusBarRef, sous peine d'hériter de son va-et-vient
341	            et de sembler apparaître puis disparaître avec la pastille dans une seule et même
342	            animation. */}
343	        <div className="absolute bottom-4 left-4 right-24 z-40 flex items-center justify-start gap-3 pointer-events-none">
344	          <div ref={statusBarRef} className="shrink-0">
345	            <div className="bg-[rgba(10,15,26,0.25)] backdrop-blur-[4px] -webkit-backdrop-blur-[4px] border-none rounded-lg px-3 py-2 text-xs text-zinc-300 flex items-center space-x-4 pointer-events-auto shadow-[0_8px_32px_0_rgba(0,0,0,0.4),0_2px_8px_0_rgba(0,0,0,0.3)]">
346	              {modelStatus ? (
347	                <>
348	                  <span className="flex items-center"><Box className="w-3.5 h-3.5 mr-1.5 text-blue-400" /> {modelStatus.name}</span>
349	                  {modelStatus.dimensions && (
350	                    <>
351	                      <span className="text-zinc-600">|</span>
352	                      <span>Dimensions: {modelStatus.dimensions.x.toFixed(1)} x {modelStatus.dimensions.z.toFixed(1)} x {modelStatus.dimensions.y.toFixed(1)} mm</span>
353	                    </>
354	                  )}
355	                  <span className="text-zinc-600">|</span>
356	                  <span className="text-emerald-400 font-medium">Ready to slice</span>
357	                </>
358	              ) : (
359	                <span className="text-zinc-400">Aucun modèle sur le plateau</span>
360	              )}
361	            </div>
362	          </div>
363	
364	          <GCodePreviewBar active={isPreviewActive} {...gcodePreview} />
365	        </div>
366	      </main>
367	    </div>
368	  );
369	};
370	
371	export default Index;

