1	import React, { useState, useRef, useEffect } from 'react';
2	import { motion, Variants } from 'framer-motion';
3	import clsx from 'clsx';
4	import {
5	  FileSliders,
6	  Box,
7	  MousePointer2,
8	  Move3d,
9	  RotateCw,
10	  Maximize,
11	  Upload,
12	  Code,
13	  Maximize2,
14	  Eye,
15	  Palette,
16	  Layers
17	} from 'lucide-react';
18	import styles from './Sidebar.module.scss';
19	import { CustomTooltip } from './CustomTooltip';
20	import { playUiSound, type UiSoundName } from '@/utils/uiSound';
21	import { GCODE_FILE_EXT } from '@/hooks/use-gcode-preview';
22	
23	// Doit correspondre à ViewCube.module.scss (`.container`) : la colonne d'outils du mode
24	// Prévisualisation vient se coller au même bord droit, juste sous le gizmo.
25	const VIEWCUBE_RIGHT = 24;
26	const VIEWCUBE_BOTTOM = 70 + 130; // top + height
27	const PREVIEW_TOOLBAR_TOP_GAP = 10; // marge entre le bas du ViewCube et le haut de la colonne
28	const PREVIEW_TOOLBAR_WIDTH = 56; // largeur de la colonne de calques en mode Prévisualisation
29	
30	// Position de repos (mode box, sans transformation) du haut de `.bottomToolbar` : top du
31	// `.container` (20px) + hauteur du `.topToolbar` (42px de bouton + 8px de padding de
32	// chaque côté = 58px) + le gap de la pile flex (10px). Doit rester en phase avec
33	// Sidebar.module.scss si ces valeurs changent.
34	const BOTTOM_TOOLBAR_REST_TOP = 20 + 58 + 10;
35	
36	// Durée totale de l'animation de déplacement/déformation du conteneur `.bottomToolbar`
37	// (voir son `transition` plus bas) : c'est le délai avant lequel les icônes du mode cible
38	// ne doivent JAMAIS commencer à apparaître (cf. `iconVariants.visible`), dans tous les sens
39	// de transition. Partagée par les deux pour qu'elles ne puissent pas diverger.
40	const CONTAINER_RESHAPE_DURATION = 1.1;
41	
42	interface SidebarProps {
43	  activeTab: '3d-view' | 'settings' | 'developer';
44	  /**
45	   * `toPreview` n'est vrai que pour l'unique cas où `tab === 'box'` signifie « vers
46	   * Prévisualisation » plutôt que « vers Préparation » (cf. handleLayerClick, branche `entering`) —
47	   * Index.tsx en a besoin pour savoir, en sortant de Modélisation, vers quelle forme (pilule ou
48	   * panneaux de Prévisualisation) jouer le morph.
49	   */
50	  onTabChange: (tab: 'box' | 'settings' | 'developer', toPreview?: boolean) => void;
51	  onOpenModel?: () => void;
52	}
53	
54	export const Sidebar: React.FC<SidebarProps> = ({
55	  activeTab,
56	  onTabChange,
57	  onOpenModel
58	}) => {
59	  const [activeTool, setActiveTool] = useState<'select' | 'move' | 'rotate' | 'scale' | 'texture' | 'layers'>('select');
60	  const [isPreviewActive, setIsPreviewActive] = useState(false);
61	  // Géométrie du conteneur juste avant de lancer la transition en cours : mesurée à la volée
62	  // (voir `playSpaceTransition`) quel que soit le mode de départ (slicer, prévisualisation
63	  // ou modélisation), pour que l'animation de conteneur parte toujours de sa forme réelle et
64	  // non d'une valeur figée valable pour un seul sens de transition.
65	  const [fromGeometry, setFromGeometry] = useState<{ x: number; y: number; width: number; height: number; borderRadius: number } | null>(null);
66	  // Largeur naturelle de la barre slicer (mode "box") : son contenu (8 boutons + 2
67	  // séparateurs) ne change jamais, donc une mesure une fois montée suffit — c'est la valeur
68	  // cible numérique vers laquelle animer au retour au mode slicer (une keyframe `"auto"`
69	  // mélangée à des nombres dans le même tableau n'anime pas correctement avec framer-motion).
70	  const [boxWidth, setBoxWidth] = useState<number | null>(null);
71	  // Décalage horizontal (en x) à appliquer en mode Prévisualisation pour que la colonne
72	  // d'outils vienne se coller au bord droit de l'écran, juste sous le gizmo ViewCube
73	  // (position fixe à `right: 24px`, voir ViewCube.module.scss) — recalculé au resize car
74	  // `.bottomToolbar` est centré par le flex column de `.container` (`left: 50%`), donc son
75	  // décalage nécessaire dépend de la largeur de la fenêtre.
76	  const [previewX, setPreviewX] = useState(0);
77	  // Décalage vertical (en y) additionnel en mode Prévisualisation, calculé pour amener le
78	  // haut de la colonne juste sous le ViewCube, quelle que soit sa position de repos réelle
79	  // (dépend de la hauteur du bandeau d'onglets du haut).
80	  const [previewY, setPreviewY] = useState(0);
81	  const bottomToolbarRef = useRef<HTMLDivElement>(null);
82	  const fileInputRef = useRef<HTMLInputElement>(null);
83	
84	  const topToolbarRef = useRef<HTMLDivElement>(null);
85	  // Slot où ModelingSidebar injecte ses boutons CAD via un portail (id stable plutôt qu'un
86	  // ref transmis en prop : les deux composants sont des siblings montés indépendamment dans
87	  // Index.tsx, un id DOM est la façon la plus simple de se retrouver).
88	  const modelingSlotRef = useRef<HTMLDivElement>(null);
89	  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
90	  const [indicatorStyle, setIndicatorStyle] = React.useState<React.CSSProperties>({});
91	
92	  /** L'onglet « Modélisation » porte la valeur 'settings'. */
93	  const isModeling = activeTab === 'settings';
94	
95	  // Gabarit cible du conteneur commun pour chaque mode — voir le commentaire au-dessus de
96	  // `.bottomToolbar` dans le JSX pour la logique d'animation qui s'en sert. En mode
97	  // Prévisualisation, x/y viennent coller la colonne au bord droit de l'écran juste sous le
98	  // ViewCube (voir l'effet qui calcule `previewX`/`previewY` plus haut) plutôt qu'un
99	  // décalage fixe indépendant de la largeur de la fenêtre.
100	  const targetGeometry = isModeling
101	    ? { x: 0, y: 0, width: 260, height: 50, borderRadius: 14 } // barre CAD (6 boutons de 38px)
102	    : isPreviewActive
103	      ? { x: previewX, y: previewY, width: PREVIEW_TOOLBAR_WIDTH, height: 340, borderRadius: 20 } // colonne de calques
104	      : { x: 0, y: 0, width: boxWidth ?? 332, height: 44, borderRadius: 22 }; // barre slicer
105	
106	  const handleUploadClick = () => {
107	    fileInputRef.current?.click();
108	  };
109	
110	  const SPACE_LABELS: Record<'box' | 'settings' | 'developer' | 'layers', string> = {
111	    box: 'Préparation',
112	    settings: 'Modélisation',
113	    developer: 'Dev',
114	    layers: 'Prévisualisation',
115	  };
116	
117	  // Son propre à l'espace d'arrivée. Pas de son pour la console Dev.
118	  const SPACE_SOUNDS: Record<'box' | 'settings' | 'developer' | 'layers', UiSoundName | null> = {
119	    box: 'spacePreparation',
120	    settings: 'spaceModeling',
121	    developer: null,
122	    layers: 'spacePreview',
123	  };
124	
125	  /**
126	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
127	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
128	   * avoir lieu pour ne jamais être visible pendant la transition. Mesure aussi la forme
129	   * actuelle du conteneur d'outils juste avant : quel que soit le mode de départ (slicer,
130	   * prévisualisation ou modélisation), c'est de là que doit partir l'animation de
131	   * déformation vers le mode suivant — jamais une valeur figée valable pour un seul sens.
132	   */
133	  const playSpaceTransition = (space: keyof typeof SPACE_LABELS, onCovered: () => void) => {
134	    const label = SPACE_LABELS[space];
135	    const sound = SPACE_SOUNDS[space];
136	    if (sound) playUiSound(sound);
137	    if (bottomToolbarRef.current) {
138	      const rect = bottomToolbarRef.current.getBoundingClientRect();
139	      const computedRadius = parseFloat(getComputedStyle(bottomToolbarRef.current).borderTopLeftRadius) || 22;
140	      // `x`/`y` ne sont pas lisibles depuis le DOM (ce sont des translate posés par
141	      // framer-motion, pas une position absolue) : on reprend ceux du mode qu'on est en
142	      // train de quitter, calculés par la même table que `targetGeometry` ci-dessous.
143	      setFromGeometry({
144	        x: targetGeometry.x,
145	        y: targetGeometry.y,
146	        width: rect.width,
147	        height: rect.height,
148	        borderRadius: computedRadius,
149	      });
150	    }
151	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
152	  };
153	
154	  const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer') => {
155	    if (tabName === 'settings' && !isModeling) {
156	      // Signale DÈS LE CLIC — avant même que le rideau plein écran ne commence à monter, pas
157	      // seulement une fois l'écran couvert (`onCovered`, ~900ms plus tard) — que les éléments sans
158	      // place dans l'espace Modélisation (ModelStatusBox, panneau du bas de Prévisualisation)
159	      // doivent commencer à disparaître : ce fondu-glissement doit être visible EN TRANSPARENCE À
160	      // TRAVERS le rideau (z-index 1000+ pour ces éléments, contre 30 pour le rideau), jamais
161	      // caché derrière lui comme le vrai changement d'onglet (`onTabChange`, lui, reste dans
162	      // `onCovered` ci-dessous : le panneau Modélisation ne doit apparaître qu'une fois l'écran
163	      // couvert).
164	      window.dispatchEvent(new CustomEvent('apex-entering-modeling'));
165	    } else if (tabName !== 'settings' && isModeling) {
166	      // Symétrique : le contenu du panneau Modélisation disparaît en cascade dès le clic, avant
167	      // que sa forme ne commence à se déformer (à `onCovered`, cf. ModelingSidebar).
168	      window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
169	    }
170	    playSpaceTransition(tabName, () => {
171	      setActiveTool('select');
172	      onTabChange(tabName);
173	      setIsPreviewActive(false);
174	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
175	    });
176	  };
177	
178	  const handleToolClick = (tool: 'select' | 'move' | 'rotate' | 'scale' | 'texture') => {
179	    const newTool = activeTool === tool ? 'select' : tool;
180	    setActiveTool(newTool);
181	    window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
182	  };
183	
184	  /**
185	   * Bascule animée vers l'espace Prévisualisation (rideau + déformation de la pilule), factorisée
186	   * hors de `handleLayerClick` pour être aussi déclenchée par le dépôt d'un fichier G-code en
187	   * Préparation (cf. l'écouteur `drop` plus bas) — même geste que le clic sur l'icône Prévisualisation,
188	   * simplement déclenché autrement. `pendingFile`, s'il est fourni, est réémis (`apex-gcode-loaded`
189	   * en pointillé via `apex-entering-preview-with-file`) une fois l'écran couvert, PAS avant : au
190	   * moment du dépôt, l'espace Prévisualisation n'a pas encore son hook de lecture actif
191	   * (`useGCodePreview(isPreviewActive)` dans Index.tsx), lequel n'écoute le dépôt/chargement que
192	   * lorsque `active` — le charger avant ce basculement n'aurait donc aucun effet.
193	   */
194	  const enterPreview = (pendingFile?: File) => {
195	    // Depuis Modélisation : même signal au clic que handleTopTabClick (cf. apex-leaving-modeling).
196	    if (isModeling) window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
197	    // L'ancien fondu séquencé des panneaux (avant le rideau plein écran) n'a plus de raison
198	    // d'être : le rideau masque déjà tout pendant que ce switch se produit, donc tout bascule
199	    // d'un coup sous le voile plutôt qu'en deux temps visibles.
200	    playSpaceTransition('layers', () => {
201	      setActiveTool('layers');
202	      // Prévisualisation est un sous-mode du slicer (Préparation), jamais de la
203	      // Modélisation : sans ce `onTabChange`, entrer en Prévisualisation depuis
204	      // Modélisation laissait `activeTab` sur 'settings', et donc le bouton
205	      // "Modélisation" restait actif (cyan) par-dessus "Prévisualisation". Le second argument
206	      // signale spécifiquement ce cas-là à Index.tsx (venant de Modélisation, vers
207	      // Prévisualisation et non vers Préparation), pour qu'il joue le bon morph de sortie.
208	      onTabChange('box', true);
209	      setIsPreviewActive(true);
210	      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'layers' } }));
211	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: true } }));
212	      // Dispatché en DERNIER, une fois `apex-preview-toggled` déjà parti : useGCodePreview
213	      // (Index.tsx) doit être passé à `active` avant de recevoir le fichier, sans quoi son
214	      // écouteur de dépôt (qui double aussi comme point d'entrée de chargement, cf.
215	      // use-gcode-preview.ts) ignorerait l'événement.
216	      if (pendingFile) {
217	        window.dispatchEvent(new CustomEvent('apex-entering-preview-with-file', { detail: { file: pendingFile } }));
218	      }
219	    });
220	  };
221	
222	  const handleLayerClick = () => {
223	    const entering = activeTool !== 'layers';
224	
225	    if (entering) {
226	      enterPreview();
227	    } else {
228	      playSpaceTransition('box', () => {
229	        setActiveTool('select');
230	        setIsPreviewActive(false);
231	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
232	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
233	      });
234	    }
235	  };
236	
237	  // Dépôt d'un fichier G-code n'importe où dans la fenêtre pendant qu'on est en Préparation (hors
238	  // Prévisualisation, hors Modélisation) : bascule automatiquement vers l'espace Prévisualisation,
239	  // avec la même animation que le clic sur son icône, puis charge le fichier une fois l'écran
240	  // découvert (cf. `enterPreview`). Un simple survol (dragenter/dragover) sans dépôt ne déclenche
241	  // rien — jamais de bascule sur un simple passage de fichier au-dessus de la fenêtre.
242	  useEffect(() => {
243	    if (isPreviewActive || isModeling) return;
244	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
245	    const onDragOver = (e: DragEvent) => {
246	      if (!hasFiles(e)) return;
247	      e.preventDefault();
248	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
249	    };
250	    const onDrop = (e: DragEvent) => {
251	      if (!hasFiles(e)) return;
252	      const file = e.dataTransfer?.files?.[0];
253	      if (!file || !GCODE_FILE_EXT.test(file.name)) return;
254	      e.preventDefault();
255	      enterPreview(file);
256	    };
257	    window.addEventListener('dragover', onDragOver);
258	    window.addEventListener('drop', onDrop);
259	    return () => {
260	      window.removeEventListener('dragover', onDragOver);
261	      window.removeEventListener('drop', onDrop);
262	    };
263	    // eslint-disable-next-line react-hooks/exhaustive-deps
264	  }, [isPreviewActive, isModeling]);
265	
266	  useEffect(() => {
267	    const handleKeyDown = (e: KeyboardEvent) => {
268	      const target = e.target as HTMLElement | null;
269	      if (target && (['INPUT', 'TEXTAREA'].includes(target.tagName) || target.isContentEditable)) {
270	        return;
271	      }
272	
273	      const key = e.key.toLowerCase();
274	      if (key === 'm') {
275	        const newTool = activeTool === 'move' ? 'select' : 'move';
276	        setActiveTool(newTool);
277	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
278	      } else if (key === 'r') {
279	        const newTool = activeTool === 'rotate' ? 'select' : 'rotate';
280	        setActiveTool(newTool);
281	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
282	      } else if (key === 's') {
283	        const newTool = activeTool === 'scale' ? 'select' : 'scale';
284	        setActiveTool(newTool);
285	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
286	      } else if (key === 't') {
287	        const newTool = activeTool === 'texture' ? 'select' : 'texture';
288	        setActiveTool(newTool);
289	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
290	      } else if (key === 'escape') {
291	        setActiveTool('select');
292	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
293	      }
294	    };
295	
296	    window.addEventListener('keydown', handleKeyDown);
297	    return () => {
298	      window.removeEventListener('keydown', handleKeyDown);
299	    };
300	  }, [activeTool]);
301	
302	  // Mesure la largeur naturelle de la barre slicer dès qu'on la voit au repos (mode box,
303	  // aucune transition en cours) — la toute première fois, et à nouveau si jamais elle
304	  // n'a pas encore été capturée (ex : l'app démarre directement sur un autre onglet).
305	  useEffect(() => {
306	    if (boxWidth === null && !isModeling && !isPreviewActive && bottomToolbarRef.current) {
307	      setBoxWidth(bottomToolbarRef.current.getBoundingClientRect().width);
308	    }
309	  }, [boxWidth, isModeling, isPreviewActive]);
310	
311	  // Décalage x/y nécessaire pour que la colonne d'outils du mode Prévisualisation vienne se
312	  // coller au bord droit de l'écran, juste sous le ViewCube. `.container` (l'ancêtre direct)
313	  // est centré par `left: 50%` quel que soit l'état, donc son centre horizontal vaut
314	  // toujours exactement `window.innerWidth / 2` — inutile de mesurer le DOM, une formule
315	  // suffit et reste valable pendant toute animation. Le `top` de repos du conteneur est lui
316	  // fixe (posé par le CSS de `.container`/`.topToolbar`, pas par une mesure runtime).
317	  useEffect(() => {
318	    const recompute = () => {
319	      const restCenterX = window.innerWidth / 2;
320	      const targetCenterX = window.innerWidth - VIEWCUBE_RIGHT - PREVIEW_TOOLBAR_WIDTH / 2;
321	      const targetTop = VIEWCUBE_BOTTOM + PREVIEW_TOOLBAR_TOP_GAP;
322	
323	      setPreviewX(targetCenterX - restCenterX);
324	      setPreviewY(targetTop - BOTTOM_TOOLBAR_REST_TOP);
325	    };
326	
327	    recompute();
328	    window.addEventListener('resize', recompute);
329	    return () => window.removeEventListener('resize', recompute);
330	  }, []);
331	
332	  useEffect(() => {
333	    if (topToolbarRef.current && buttonRefs.current.size > 0) {
334	      const activeButtonKey = activeTool === 'layers' ? 'layers' : (activeTab === '3d-view' ? 'box' : activeTab);
335	      const activeButton = buttonRefs.current.get(activeButtonKey);
336	
337	      if (activeButton) {
338	        const toolbarRect = topToolbarRef.current.getBoundingClientRect();
339	        const buttonRect = activeButton.getBoundingClientRect();
340	
341	        setIndicatorStyle({
342	          width: buttonRect.width,
343	          height: buttonRect.height,
344	          left: buttonRect.left - toolbarRect.left,
345	          top: buttonRect.top - toolbarRect.top,
346	          opacity: 1,
347	        });
348	      } else {
349	        setIndicatorStyle((prev) => ({ ...prev, opacity: 0 }));
350	      }
351	    }
352	  }, [activeTab, activeTool]);
353	
354	  const iconVariants: Variants = {
355	    // Les icônes du mode cible n'apparaissent qu'UNE FOIS le reshape du conteneur terminé
356	    // (durée totale de l'animation de `.bottomToolbar`, voir CONTAINER_RESHAPE_DURATION) —
357	    // dans tous les sens de transition, pas seulement Prévisualisation→Modélisation. Sans ce
358	    // délai de base, les icônes du nouveau mode démarraient leur propre petit délai en
359	    // cascade (`i*0.04`) dès le changement de state React, bien avant que le conteneur ait
360	    // fini de se déplacer/déformer.
361	    visible: (i: number) => ({
362	      opacity: 1,
363	      y: 0,
364	      scale: 1,
365	      transition: {
366	        delay: CONTAINER_RESHAPE_DURATION + i * 0.04,
367	        duration: 0.3,
368	        ease: [0.16, 1, 0.3, 1] as const
369	      }
370	    }),
371	    // La sortie, elle, doit rester immédiate : les icônes du mode qu'on quitte doivent avoir
372	    // disparu AVANT que le conteneur ne commence à se déformer (cf. keyframes `times` de
373	    // `.bottomToolbar` : vidage sur les premiers 45%, déformation sur les 55% restants).
374	    hidden: (i: number) => ({
375	      opacity: 0,
376	      y: 15,
377	      scale: 0.95,
378	      transition: {
379	        delay: i * 0.04,
380	        duration: 0.25,
381	        ease: [0.25, 1, 0.5, 1] as const
382	      }
383	    })
384	  };
385	
386	  return (
387	    <div className={styles.container} data-apex-chrome-panel>
388	      {/* Top Toolbar (Navigation & Main Views) */}
389	      <div
390	        ref={topToolbarRef}
391	        className={clsx(styles.toolbar, styles.topToolbar)}
392	      >
393	        <div className={styles.activeIndicator} style={indicatorStyle}></div>
394	
395	        <CustomTooltip content="Apex Slicer Studio" description="Logiciel de préparation et de découpe 3D haute performance pour l'impression additive professionnelle.">
396	          <div className={styles.logoContainer}>
397	            <img src="/logo.svg" alt="Logo" className={styles.logoImg} />
398	          </div>
399	        </CustomTooltip>
400	
401	        <div className={styles.topSeparator} />
402	
403	        <CustomTooltip content="Vue 3D Perspective" description="Basculez sur l'espace de travail principal pour inspecter et manipuler vos modèles sur le plateau d'impression.">
404	          <button
405	            ref={(el) => { if (el) buttonRefs.current.set('box', el); }}
406	            className={clsx(styles.button, styles.topButton, {
407	              [styles.active]: activeTab === '3d-view' && !isPreviewActive,
408	            })}
409	            onClick={() => handleTopTabClick('box')}
410	          >
411	            <FileSliders size={22} />
412	            <span className={styles.topButtonLabel}>Préparation</span>
413	          </button>
414	        </CustomTooltip>
415	
416	        <CustomTooltip content="Prévisualisation" description="Visualisez le parcours de la buse et ajustez différents paramètres si cela ne vous convient pas.">
417	          <button
418	            ref={(el) => { if (el) buttonRefs.current.set('layers', el); }}
419	            className={clsx(styles.button, styles.topButton, {
420	              [styles.active]: isPreviewActive,
421	            })}
422	            onClick={handleLayerClick}
423	          >
424	            <Layers size={22} />
425	            <span className={styles.topButtonLabel}>Prévisualisation</span>
426	          </button>
427	        </CustomTooltip>
428	
429	        <CustomTooltip content="Modélisation" description="Accédez aux outils de modélisation et de préparation de votre modèle.">
430	          <button
431	            ref={(el) => { if (el) buttonRefs.current.set('settings', el); }}
432	            className={clsx(styles.button, styles.topButton, {
433	              [styles.active]: activeTab === 'settings',
434	            })}
435	            onClick={() => handleTopTabClick('settings')}
436	          >
437	            <Box size={22} />
438	            <span className={styles.topButtonLabel}>Modélisation</span>
439	          </button>
440	        </CustomTooltip>
441	
442	        <CustomTooltip content="Console Développeur" description="Inspectez les flux G-code générés en temps réel et les journaux de diagnostic système.">
443	          <button
444	            ref={(el) => { if (el) buttonRefs.current.set('developer', el); }}
445	            className={clsx(styles.button, styles.topButton, {
446	              [styles.active]: activeTab === 'developer',
447	            })}
448	            onClick={() => handleTopTabClick('developer')}
449	          >
450	            <Code size={22} />
451	            <span className={styles.topButtonLabel}>Dev</span>
452	          </button>
453	        </CustomTooltip>
454	      </div>
455	
456	      {/* Bottom Toolbar (Action, Manipulation 3D) — UN SEUL conteneur physique pour les 3
457	          modes (slicer / prévisualisation / modélisation) : il ne se démonte jamais, il se
458	          vide de ses icônes, se déplace et se déforme, puis affiche les icônes du mode
459	          suivant. En mode modélisation les boutons CAD ne sont pas rendus ici : ils vivent
460	          dans ModelingSidebar (toute la logique de features y reste), qui les injecte dans
461	          `modelingSlotRef` via un portail — même noeud DOM, contenu apporté par le
462	          propriétaire de sa logique. */}
463	      <motion.div
464	        ref={bottomToolbarRef}
465	        className={clsx(styles.toolbar, styles.bottomToolbar)}
466	        initial={false}
467	        animate={fromGeometry ? {
468	          // Toute transition (slicer ↔ prévisualisation, slicer ↔ modélisation) part
469	          // TOUJOURS de la forme réellement mesurée juste avant (`fromGeometry`) pour
470	          // rejoindre le gabarit du mode cible — un seul et même conteneur qui se vide de
471	          // ses icônes (cf. iconVariants), se déplace et se déforme, jamais deux
472	          // composants qui se croisent.
473	          x: [fromGeometry.x, fromGeometry.x, targetGeometry.x],
474	          y: [fromGeometry.y, fromGeometry.y, targetGeometry.y],
475	          width: [fromGeometry.width, fromGeometry.width, targetGeometry.width],
476	          height: [fromGeometry.height, fromGeometry.height, targetGeometry.height],
477	          borderRadius: [fromGeometry.borderRadius, fromGeometry.borderRadius, targetGeometry.borderRadius],
478	          opacity: 1,
479	          marginTop: 0
480	        } : {
481	          // État initial (avant toute transition jouée) : forme de repos du mode courant,
482	          // sans animation. "auto" tant que la largeur naturelle n'a pas encore été mesurée
483	          // (premier rendu), un nombre dès qu'elle l'est — évite un saut visuel une fois
484	          // `boxWidth` connu puisque `targetGeometry.width` vaudra alors la même valeur.
485	          x: targetGeometry.x,
486	          y: targetGeometry.y,
487	          width: isModeling || boxWidth !== null ? targetGeometry.width : "auto",
488	          height: targetGeometry.height,
489	          borderRadius: targetGeometry.borderRadius,
490	          opacity: 1,
491	          marginTop: 0
492	        }}
493	        transition={{
494	          duration: CONTAINER_RESHAPE_DURATION,
495	          times: [0, 0.45, 1],
496	          ease: [0.25, 1, 0.5, 1]
497	        }}
498	        style={{ originX: 0.5, originY: 0.5, pointerEvents: 'auto' }}
499	      >
500	        <motion.div custom={0} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
501	          <CustomTooltip content="Outil de Sélection" description="Cliquez sur n'importe quel modèle 3D sur le plateau pour le sélectionner et afficher ses propriétés.">
502	            <button
503	              className={clsx(styles.button, styles.bottomButton, {
504	                [styles.active]: activeTool === 'select',
505	              })}
506	              onClick={() => handleToolClick('select')}
507	            >
508	              <MousePointer2 size={16} />
509	            </button>
510	          </CustomTooltip>
511	        </motion.div>
512	
513	        <motion.div custom={1} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
514	          <CustomTooltip content="Outil de Déplacement (Move - M)" description="Affichez les gizmos directionnels pour repositionner précisément l'objet sur le plateau d'impression. (Raccourci : M)">
515	            <button
516	              className={clsx(styles.button, styles.bottomButton, {
517	                [styles.active]: activeTool === 'move',
518	              })}
519	              onClick={() => handleToolClick('move')}
520	            >
521	              <Move3d size={16} />
522	            </button>
523	          </CustomTooltip>
524	        </motion.div>
525	
526	        <motion.div custom={2} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
527	          <CustomTooltip content="Outil de Rotation (Rotate - R)" description="Faites pivoter le modèle selon les axes X, Y et Z pour optimiser son orientation de contact. (Raccourci : R)">
528	            <button
529	              className={clsx(styles.button, styles.bottomButton, {
530	                [styles.active]: activeTool === 'rotate',
531	              })}
532	              onClick={() => handleToolClick('rotate')}
533	            >
534	              <RotateCw size={16} />
535	            </button>
536	          </CustomTooltip>
537	        </motion.div>
538	
539	        <motion.div custom={3} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
540	          <CustomTooltip content="Outil de Mise à l'échelle (Scale - S)" description="Modifiez la taille et les proportions du modèle 3D sur le plateau d'impression. (Raccourci : S)">
541	            <button
542	              className={clsx(styles.button, styles.bottomButton, {
543	                [styles.active]: activeTool === 'scale',
544	              })}
545	              onClick={() => handleToolClick('scale')}
546	            >
547	              <Maximize size={16} />
548	            </button>
549	          </CustomTooltip>
550	        </motion.div>
551	
552	        <motion.div custom={4} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
553	          <CustomTooltip content="Outil Texture & Matériau (Texture - T)" description="Sélectionnez et éditez les textures et propriétés de matériaux du modèle actif. (Raccourci : T)">
554	            <button
555	              className={clsx(styles.button, styles.bottomButton, {
556	                [styles.active]: activeTool === 'texture',
557	              })}
558	              onClick={() => handleToolClick('texture')}
559	            >
560	              <Palette size={16} />
561	            </button>
562	          </CustomTooltip>
563	        </motion.div>
564	
565	        <motion.div custom={5} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
566	          <div className={styles.separator} />
567	        </motion.div>
568	
569	        <motion.div custom={6} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
570	          <CustomTooltip content="Réinitialiser la Caméra" description="Remettez la caméra dans sa position isométrique par défaut face au plateau.">
571	            <button
572	              className={clsx(styles.button, styles.bottomButton)}
573	              onClick={() => window.dispatchEvent(new CustomEvent('apex-reset-camera'))}
574	            >
575	              <Eye size={16} />
576	            </button>
577	          </CustomTooltip>
578	        </motion.div>
579	
580	        <motion.div custom={7} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
581	          <CustomTooltip content="Ajuster à l'Écran (Fit)" description="Zoomez et recentrez la vue automatiquement sur le modèle sélectionné.">
582	            <button
583	              className={clsx(styles.button, styles.bottomButton)}
584	              onClick={() => window.dispatchEvent(new CustomEvent('apex-fit-screen'))}
585	            >
586	              <Maximize2 size={16} />
587	            </button>
588	          </CustomTooltip>
589	        </motion.div>
590	
591	        <motion.div custom={8} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
592	          <div className={styles.separator} />
593	        </motion.div>
594	
595	        <motion.div custom={9} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
596	          <CustomTooltip content="Importer un Modèle 3D (.stl, .glb, .gltf)" description="Ouvrez le sélecteur de fichiers pour charger un nouveau fichier 3D avec textures sur le plateau.">
597	            <button
598	              className={clsx(styles.button, styles.bottomButton, styles.uploadActionButton)}
599	              onClick={handleUploadClick}
600	            >
601	              <Upload size={16} />
602	            </button>
603	          </CustomTooltip>
604	        </motion.div>
605	
606	        {/* Mode modélisation : mêmes noeud et animation de conteneur que le mode slicer —
607	            seul le contenu diffère. Les boutons CAD eux-mêmes (logique de features) sont
608	            possédés par ModelingSidebar, qui les injecte ici via un portail (voir
609	            modelingSlotRef) plutôt que d'être dupliqués ou recréés dans ce composant. */}
610	        <motion.div
611	          custom={0}
612	          variants={iconVariants}
613	          animate={isModeling ? "visible" : "hidden"}
614	          initial="hidden"
615	          ref={modelingSlotRef}
616	          id="apex-modeling-toolbar-slot"
617	          className={styles.modelingSlot}
618	        />
619	
620	        <input
621	          type="file"
622	          ref={fileInputRef}
623	          style={{ display: 'none' }}
624	          accept=".stl,.glb,.gltf"
625	          onChange={(e) => {
626	            if (e.target.files?.[0]) {
627	              window.dispatchEvent(
628	                new CustomEvent('apex-import-model', {
629	                  detail: e.target.files[0],
630	                })
631	              );
632	            }
633	            // Réinitialise la valeur pour pouvoir réimporter exactement le même fichier
634	            // à la suite (sinon le navigateur ne redéclenche pas onChange).
635	            e.target.value = '';
636	          }}
637	        />
638	      </motion.div>
639	    </div>
640	  );
641	};

