1	import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
2	import clsx from 'clsx';
3	import { animate, motion, useMotionValue, type AnimationPlaybackControls } from 'framer-motion';
4	import styles from './TopRightMenu.module.scss';
5	
6	// Même tempo que la barre d'outils de la Sidebar au changement d'espace
7	// (CONTAINER_RESHAPE_DURATION = 1.1 s, immobile pendant les 45 % premiers, même courbe). Le
8	// déplacement se fait ensuite en L, un axe après l'autre, jamais en diagonale :
9	//  - vers la Prévisualisation : vers la gauche, puis vers le haut ;
10	//  - retour : vers le bas, puis vers la droite.
11	const RESHAPE_DURATION = 1.1;
12	const RESHAPE_TIMES = [0, 0.45, 0.725, 1];
13	const RESHAPE_EASE = [0.25, 1, 0.5, 1] as const;
14	
15	/** Largeur de la barre d'aide en Prévisualisation (bornée par `max-width` en CSS). */
16	const PREVIEW_WIDTH = 666;
17	
18	interface Geometry {
19	  left: number;
20	  bottom: number;
21	  width: number;
22	}
23	
24	export const TopRightMenu: React.FC = () => {
25	  const [tooltipDesc, setTooltipDesc] = useState("Survolez n'importe quel élément interactif de l'interface pour afficher sa description détaillée en temps réel.");
26	  // En Prévisualisation, la barre d'aide quitte le centre pour le coin bas gauche.
27	  const [previewActive, setPreviewActive] = useState(false);
28	
29	  const containerRef = useRef<HTMLDivElement>(null);
30	  const toolbarRef = useRef<HTMLDivElement>(null);
31	  // Position de départ, mesurée juste avant le changement d'espace.
32	  const fromRef = useRef<Geometry | null>(null);
33	  const animationsRef = useRef<AnimationPlaybackControls[]>([]);
34	
35	  const x = useMotionValue(0);
36	  const y = useMotionValue(0);
37	  const width = useMotionValue<number | string>('auto');
38	
39	  useEffect(() => {
40	    const handleGlobalTooltip = (e: CustomEvent<{ title: string; desc: string }>) => {
41	      if (e.detail) {
42	        setTooltipDesc(e.detail.desc);
43	      }
44	    };
45	
46	    const handleResetTooltip = () => {
47	      setTooltipDesc("Survolez n'importe quel élément interactif de l'interface pour afficher sa description détaillée en temps réel.");
48	    };
49	
50	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
51	      const el = toolbarRef.current;
52	      if (el) {
53	        const r = el.getBoundingClientRect();
54	        fromRef.current = { left: r.left, bottom: window.innerHeight - r.bottom, width: r.width };
55	      }
56	      setPreviewActive(!!e.detail?.active);
57	    };
58	
59	    window.addEventListener('apex-set-tooltip', handleGlobalTooltip as EventListener);
60	    window.addEventListener('apex-reset-tooltip', handleResetTooltip);
61	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
62	
63	    return () => {
64	      window.removeEventListener('apex-set-tooltip', handleGlobalTooltip as EventListener);
65	      window.removeEventListener('apex-reset-tooltip', handleResetTooltip);
66	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
67	    };
68	  }, []);
69	
70	  // Au changement d'espace, avant affichage : la barre est d'abord posée par le CSS à sa place
71	  // de repos dans le nouvel espace pour mesurer l'arrivée, puis le conteneur passe en
72	  // positionnement libre (coin bas gauche de la fenêtre) le temps de l'animation, et x / y /
73	  // largeur parcourent le trajet en pixels. À la fin, le CSS reprend la main à la même place.
74	  useLayoutEffect(() => {
75	    const from = fromRef.current;
76	    const container = containerRef.current;
77	    const el = toolbarRef.current;
78	    fromRef.current = null;
79	    const restWidth = previewActive ? PREVIEW_WIDTH : 'auto';
80	    animationsRef.current.forEach((a) => a.stop());
81	    animationsRef.current = [];
82	    if (!from || !container || !el) {
83	      width.set(restWidth);
84	      return;
85	    }
86	
87	    // framer-motion n'écrit les MotionValue dans le DOM qu'à l'image suivante : on écrit aussi le
88	    // style tout de suite, pour mesurer juste et basculer la classe sans image intermédiaire.
89	    const setNow = (xv: number, yv: number, wv: number | string) => {
90	      x.set(xv);
91	      y.set(yv);
92	      width.set(wv);
93	      el.style.transform = `translateX(${xv}px) translateY(${yv}px)`;
94	      el.style.width = typeof wv === 'number' ? `${wv}px` : wv;
95	    };
96	
97	    container.classList.remove(styles.containerAnimating);
98	    setNow(0, 0, restWidth);
99	    const r = el.getBoundingClientRect();
100	    const to: Geometry = { left: r.left, bottom: window.innerHeight - r.bottom, width: r.width };
101	
102	    container.classList.add(styles.containerAnimating);
103	    // Aller : horizontal puis vertical ; retour : vertical puis horizontal.
104	    const horizontalFirst = previewActive;
105	    const path = (a: number, b: number, first: boolean) => (first ? [a, a, b, b] : [a, a, a, b]);
106	    const transition = { duration: RESHAPE_DURATION, times: RESHAPE_TIMES, ease: RESHAPE_EASE };
107	    const xs = path(from.left, to.left, horizontalFirst);
108	    const ys = path(-from.bottom, -to.bottom, !horizontalFirst);
109	    const ws = path(from.width, to.width, horizontalFirst);
110	    setNow(xs[0], ys[0], ws[0]);
111	
112	    const done = animate(x, xs, transition);
113	    animationsRef.current = [done, animate(y, ys, transition), animate(width, ws, transition)];
114	    done.then(() => {
115	      if (!animationsRef.current.includes(done)) return; // remplacée par une animation plus récente
116	      container.classList.remove(styles.containerAnimating);
117	      setNow(0, 0, restWidth);
118	    });
119	    // `x`, `y`, `width` sont des MotionValue stables : seul le changement d'espace compte.
