1	import React, { useEffect, useState, useRef, useLayoutEffect } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import styles from './SpaceTransitionOverlay.module.scss';
4	
5	/**
6	 * Rideau plein écran joué à chaque changement d'espace (Préparation / Prévisualisation /
7	 * Modélisation / Dev), en 4 étapes STRICTEMENT séquentielles (le flou est entièrement terminé
8	 * avant que le voile ne commence à apparaître — jamais les deux à la fois) :
9	 *   1. blur    — flou de l'interface, sans aucune teinte de couleur.
10	 *   2. paint   — une fois le flou installé, le voile bleu opaque est « peint » par grosses tuiles
11	 *                (grille TILE_COLS × TILE_ROWS), chacune apparaissant avec un délai croissant
12	 *                selon sa distance au coin haut-droit, façon touches de pinceau qui balaient
13	 *                l'écran en diagonale vers le coin bas-gauche.
14	 *   3. text    — le texte apparaît une fois toutes les tuiles posées ("APEX" en Ethnocentric, le
15	 *                nom de l'espace en Orbitron) ; c'est aussi à ce moment que le switch réel a lieu.
16	 *   4. fadeout — même effet de tuiles que l'apparition, rejoué à l'identique (mêmes délais, même
17	 *                balayage diagonal) mais en disparition ; le flou se dissipe en même temps,
18	 *                révélant le nouvel espace.
19	 *
20	 * Piloté par l'événement `apex-space-transition` (voir Sidebar.tsx, seul émetteur) plutôt qu'un
21	 * state React partagé, pour rester cohérent avec le bus d'événements global du reste de l'app
22	 * (cf. CLAUDE.md).
23	 */
24	
25	const BLUR_MS = 320;      // 1. montée du flou seul, doit être TERMINÉE avant la moindre tuile
26	// Tuiles 3× plus petites (en aire) que la grille précédente (8×5) : même ratio, dimensions
27	// multipliées par √3.
28	const TILE_COLS = 14;
29	const TILE_ROWS = 9;
30	// Réduit par rapport à la grille précédente (8×5, pas 28ms) pour garder une durée de balayage
31	// comparable malgré la diagonale plus longue (14+9 vs 8+5 pas).
32	const TILE_STEP_MS = 15;  // délai entre deux tuiles consécutives dans l'ordre de balayage
33	const TILE_ANIM_MS = 260; // durée d'apparition d'une tuile individuelle
34	// Le dernier délai + sa propre durée d'anim = durée totale de la phase "paint".
35	const PAINT_MS = (TILE_COLS + TILE_ROWS - 2) * TILE_STEP_MS + TILE_ANIM_MS;
36	// 3. texte affiché, voile plein écran (switch réel ici). La barre sous le nom de l'espace
37	// (.scanline) rejoue SCANLINE_REPEAT fois, une fois par seconde, avant que l'espace ne soit
38	// dévoilé — le texte reste donc affiché au moins le temps que ces répétitions se terminent.
39	// Seule la destination "Modélisation" a droit à 6 répétitions ; toutes les autres (Préparation,
40	// Prévisualisation, Dev...) gardent le nombre par défaut.
41	const SCANLINE_CYCLE_MS = 1000;
42	const SCANLINE_REPEAT_DEFAULT = 1;
43	const SCANLINE_REPEAT_MODELING = 6;
44	const getScanlineRepeat = (label: string) => (label === 'Modélisation' ? SCANLINE_REPEAT_MODELING : SCANLINE_REPEAT_DEFAULT);
45	const getTextMs = (label: string) => SCANLINE_CYCLE_MS * getScanlineRepeat(label);
46	const FADEOUT_MS = PAINT_MS; // 4. même effet de tuiles que l'apparition, même durée totale
47	
48	type Phase = 'blur' | 'paint' | 'text' | 'fadeout';
49	
50	interface SpaceTransitionDetail {
51	  label: string;
52	  onCovered?: () => void;
53	}
54	
55	// Grille de tuiles avec leur délai de balayage : distance (en pas de grille) au coin haut-droit,
56	// donc la tuile (col=COLS-1, row=0) part la première et (col=0, row=ROWS-1) la dernière — un
57	// vrai balayage diagonal plutôt qu'un simple décalage ligne par ligne.
58	const TILES = Array.from({ length: TILE_COLS * TILE_ROWS }, (_, i) => {
59	  const col = i % TILE_COLS;
60	  const row = Math.floor(i / TILE_COLS);
61	  const distance = (TILE_COLS - 1 - col) + row;
62	  return { col, row, delayMs: distance * TILE_STEP_MS };
63	});
64	
65	// Largeur cible (en px) que le nom de l'espace doit occuper, quel que soit le nombre de
66	// lettres — c'est ce qui fait que "DEV" et "PRÉVISUALISATION" remplissent tous les deux le
67	// même cadre plutôt que d'avoir un espacement de lettres fixe (donc une largeur qui varie
68	// avec la longueur du mot).
69	const SPACE_NAME_TARGET_WIDTH_PX = 260;
70	
71	export const SpaceTransitionOverlay: React.FC = () => {
72	  const [label, setLabel] = useState<string | null>(null);
73	  const [phase, setPhase] = useState<Phase>('blur');
74	  const timeoutsRef = useRef<number[]>([]);
75	  // Change à chaque déclenchement pour forcer framer-motion à rejouer l'apparition des tuiles
76	  // (sans clé, une 2e transition juste après la 1re les laisserait déjà toutes posées).
77	  const [runId, setRunId] = useState(0);
78	  const spaceNameRef = useRef<HTMLSpanElement>(null);
79	  // Espacement de lettres recalculé pour chaque `label` afin que le texte remplisse toujours
80	  // SPACE_NAME_TARGET_WIDTH_PX, au lieu d'un `letter-spacing` fixe qui laisse un mot court
81	  // (« Dev ») loin de remplir le cadre et un mot long (« Prévisualisation ») le déborder.
82	  const [spaceNameLetterSpacing, setSpaceNameLetterSpacing] = useState(0.5);
83	  const painted = phase === 'text' || phase === 'fadeout';
84	
85	  useLayoutEffect(() => {
86	    const el = spaceNameRef.current;
87	    if (!label || !el) return;
88	
89	    // Mesure la largeur du texte SANS espacement de lettres ajouté, pour en déduire combien
90	    // en ajouter par intervalle afin d'atteindre la largeur cible.
91	    el.style.letterSpacing = '0px';
92	    const naturalWidth = el.getBoundingClientRect().width;
93	    const gapCount = Math.max(label.length - 1, 1);
94	    const extraPx = Math.max(SPACE_NAME_TARGET_WIDTH_PX - naturalWidth, 0);
95	    const fontSize = parseFloat(getComputedStyle(el).fontSize) || 15;
96	    const spacingEm = extraPx / gapCount / fontSize;
97	
98	    setSpaceNameLetterSpacing(spacingEm);
99	    // Dépend aussi de `painted` : le <span> n'existe dans le DOM qu'une fois les tuiles posées
100	    // (rendu conditionnel plus bas), donc au moment où `label` change seul le ref est encore
101	    // null — il faut remesurer une fois le nœud monté.
102	  }, [label, painted]);
103	
104	  useEffect(() => {
105	    const clearTimeouts = () => {
106	      timeoutsRef.current.forEach((id) => window.clearTimeout(id));
107	      timeoutsRef.current = [];
108	    };
109	
110	    const handleTransition = (e: Event) => {
111	      const detail = (e as CustomEvent<SpaceTransitionDetail>).detail;
112	      if (!detail?.label) return;
113	
114	      const textMs = getTextMs(detail.label);
115	      const totalMs = BLUR_MS + PAINT_MS + textMs + FADEOUT_MS;
116	
117	      clearTimeouts();
118	      setLabel(detail.label);
119	      setPhase('blur');
120	      setRunId((id) => id + 1);
121	
122	      timeoutsRef.current.push(
123	        window.setTimeout(() => setPhase('paint'), BLUR_MS),
124	        window.setTimeout(() => {
125	          // Le contenu change une fois toutes les tuiles posées, jamais visible.
126	          detail.onCovered?.();
127	          setPhase('text');
128	        }, BLUR_MS + PAINT_MS),
129	        window.setTimeout(() => setPhase('fadeout'), BLUR_MS + PAINT_MS + textMs),
130	        window.setTimeout(() => setLabel(null), totalMs),
131	      );
132	    };
133	
134	    window.addEventListener('apex-space-transition', handleTransition);
135	    return () => {
136	      window.removeEventListener('apex-space-transition', handleTransition);
137	      clearTimeouts();
138	    };
139	  }, []);
140	
141	  const fadingOut = phase === 'fadeout';
142	
143	  return (
144	    <AnimatePresence>
145	      {label && (
146	        <div className={styles.overlay}>
147	          {/* Étape 1 : flou seul, sans teinte — entièrement monté avant la moindre tuile. */}
148	          <motion.div
149	            className={styles.blurLayer}
150	            initial={{ backdropFilter: 'blur(0px)' }}
151	            animate={{ backdropFilter: fadingOut ? 'blur(0px)' : 'blur(18px)' }}
152	            transition={{ duration: (fadingOut ? FADEOUT_MS : BLUR_MS) / 1000, ease: [0.4, 0, 0.2, 1] }}
153	          />
154	
155	          {/* Étape 2 (paint) / 4 (fadeout) : mêmes tuiles, même balayage et mêmes délais dans les
156	              deux sens — seule la cible (posée vs. retirée) change avec `fadingOut`. */}
157	          <div className={styles.tileGrid}>
158	            {phase !== 'blur' && TILES.map(({ col, row, delayMs }) => (
159	              <motion.div
160	                key={`${runId}-${col}-${row}`}
161	                className={styles.tile}
162	                style={{
163	                  left: `${(col / TILE_COLS) * 100}%`,
164	                  top: `${(row / TILE_ROWS) * 100}%`,
165	                  width: `${100 / TILE_COLS}%`,
166	                  height: `${100 / TILE_ROWS}%`,
167	                }}
168	                initial={{ opacity: 0, scale: 1.3 }}
169	                animate={fadingOut ? { opacity: 0, scale: 1.3 } : { opacity: 1, scale: 1 }}
170	                transition={{ duration: TILE_ANIM_MS / 1000, delay: delayMs / 1000, ease: [0.16, 1, 0.3, 1] }}
171	              />
172	            ))}
173	          </div>
174	
175	          <AnimatePresence>
176	            {painted && (
177	              <motion.div
178	                className={styles.textBlock}
179	                initial={{ opacity: 0, scale: 0.85, letterSpacing: '0.4em' }}
180	                animate={{ opacity: fadingOut ? 0 : 1, scale: 1, letterSpacing: '0.15em' }}
181	                exit={{ opacity: 0, scale: 1.08, letterSpacing: '0.5em' }}
182	                transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
183	              >
184	                <span className={styles.brand}>APEX</span>
185	                <span
186	                  ref={spaceNameRef}
187	                  className={styles.spaceName}
188	                  style={{ letterSpacing: `${spaceNameLetterSpacing}em` }}
189	                >
190	                  {label}
191	                </span>
192	                {!fadingOut && (
193	                  <motion.span
194	                    className={styles.scanline}
195	                    initial={{ scaleX: 0, opacity: 0.9 }}
196	                    animate={{ scaleX: 1, opacity: 0 }}
197	                    transition={{
198	                      duration: 0.5,
199	                      ease: 'easeOut',
200	                      repeat: getScanlineRepeat(label) - 1,
