15	  name: string;
16	  children: SubMeshItem[];
17	}
18	
19	export const ModelStatusBox: React.FC = () => {
20	  const [models, setModels] = useState<ModelItem[]>([]);
21	  const [selectedModelName, setSelectedModelName] = useState<string | null>(null);
22	  const [selectedModelNames, setSelectedModelNames] = useState<Set<string>>(new Set());
23	  const [expandedModels, setExpandedModels] = useState<Record<string, boolean>>({});
24	  const [previewActive, setPreviewActive] = useState(false);
25	  // Le mode modélisation a sa propre arborescence (les corps) : celle des modèles importés
26	  // ferait doublon, on l'escamote comme en mode Prévisualisation.
27	  const [modelingActive, setModelingActive] = useState(false);
28	  const toolbarRef = useRef<HTMLDivElement>(null);
29	
30	  useEffect(() => {
31	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
32	      setPreviewActive(!!e.detail?.active);
33	    };
34	    const handleModeChanged = (e: CustomEvent<{ mode: 'slicer' | 'modeling' }>) => {
35	      setModelingActive(e.detail?.mode === 'modeling');
36	    };
37	    // Dispatché par Sidebar.tsx dès le CLIC vers Modélisation, avant même que le rideau plein écran
38	    // ne commence à monter — ce panneau doit disparaître EN TRANSPARENCE À TRAVERS le rideau qui
39	    // monte (cf. ELEMENTS_FADE_MS), pas seulement une fois `apex-mode-changed` reçu (dispatché par
40	    // ModelingSidebar à son montage, lui-même retardé jusqu'à ce que le rideau ait fini de couvrir
41	    // l'écran — bien trop tard pour ce fondu).
42	    const handleEnteringModeling = () => setModelingActive(true);
43	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
44	    window.addEventListener('apex-mode-changed', handleModeChanged as EventListener);
45	    window.addEventListener('apex-entering-modeling', handleEnteringModeling);
46	    return () => {
47	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
48	      window.removeEventListener('apex-mode-changed', handleModeChanged as EventListener);
49	      window.removeEventListener('apex-entering-modeling', handleEnteringModeling);
50	    };
51	  }, []);
52	
53	  useEffect(() => {
54	    const handleMeshSelected = (e: CustomEvent<{ name: string | null; names?: string[]; subMeshes?: SubMeshItem[] }>) => {
55	      setSelectedModelNames(new Set(e.detail?.names ?? (e.detail?.name ? [e.detail.name] : [])));
56	      if (e.detail?.name) {
57	        setSelectedModelName(e.detail.name);
58	        if (e.detail.subMeshes) {
59	          setModels(prev => {
60	            const exists = prev.some(m => m.name === e.detail.name);
61	            if (!exists) {
62	              return [...prev, {
63	                id: Date.now().toString(),
64	                name: e.detail.name!,
65	                children: e.detail.subMeshes!
66	              }];
67	            }
68	            return prev.map(m => m.name === e.detail.name ? { ...m, children: e.detail.subMeshes! } : m);
69	          });
70	        }
71	      } else {
72	        setSelectedModelName(null);
73	      }
74	    };
75	
76	    const handleImportModel = (e: CustomEvent<File>) => {
77	      if (e.detail) {
78	        const fileName = e.detail.name;
79	        setSelectedModelName(fileName);
80	      }
81	    };
82	
83	    const handleMeshDeleted = (e: CustomEvent<{ name?: string }>) => {
84	      const deletedName = e.detail?.name;
85	      if (deletedName) {
86	        setModels(prev => prev.filter(m => m.name !== deletedName));
87	        if (selectedModelName === deletedName) {
88	          setSelectedModelName(null);
89	        }
90	        setSelectedModelNames(prev => {
91	          const next = new Set(prev);
92	          next.delete(deletedName);
93	          return next;
94	        });
95	      } else {
96	        setModels([]);
97	        setSelectedModelName(null);
98	        setSelectedModelNames(new Set());
99	      }
100	    };
101	
102	    window.addEventListener('apex-mesh-selected', handleMeshSelected as EventListener);
103	    window.addEventListener('apex-import-model', handleImportModel as EventListener);
104	    window.addEventListener('apex-mesh-deleted', handleMeshDeleted as EventListener);
105	
106	    return () => {
107	      window.removeEventListener('apex-mesh-selected', handleMeshSelected as EventListener);
108	      window.removeEventListener('apex-import-model', handleImportModel as EventListener);
109	      window.removeEventListener('apex-mesh-deleted', handleMeshDeleted as EventListener);
110	    };
111	  }, [selectedModelName]);
112	
113	  const toggleExpand = (modelName: string, e: React.MouseEvent) => {
114	    e.stopPropagation();
115	    setExpandedModels(prev => ({
116	      ...prev,
117	      [modelName]: !prev[modelName]
118	    }));
119	  };
120	
121	  // Ce panneau grandit avec l'arborescence (dépliage d'un modèle) : la pilule Qualité/Solidité/
122	  // Vitesse (CategoriesSidebar), positionnée juste en-dessous, doit alors être repoussée d'autant
123	  // pour que la marge (MODEL_TREE_PILL_GAP) reste TOUJOURS respectée, plutôt que de se faire
124	  // recouvrir ou coller. On mesure la hauteur réellement rendue et on ne diffuse un décalage que
125	  // lorsque le bord bas réel + la marge dépasse la position par défaut de la pilule (PILL_TOP).
126	  useEffect(() => {
127	    const el = toolbarRef.current;
128	    if (!el || previewActive || modelingActive) {
129	      window.dispatchEvent(new CustomEvent('apex-model-tree-resized', { detail: { overflow: 0 } }));
130	      return;
131	    }
132	    const notify = () => {
133	      const requiredTop = MODEL_TREE_TOP + el.offsetHeight + MODEL_TREE_PILL_GAP;
134	      const overflow = Math.max(0, requiredTop - PILL_TOP);
135	      window.dispatchEvent(new CustomEvent('apex-model-tree-resized', { detail: { overflow } }));
136	    };
137	    const observer = new ResizeObserver(notify);
138	    observer.observe(el);
139	    notify();
140	    return () => {
141	      observer.disconnect();
142	      window.dispatchEvent(new CustomEvent('apex-model-tree-resized', { detail: { overflow: 0 } }));
143	    };
144	  }, [previewActive, modelingActive]);
145	
146	  return (
147	    <div className={styles.container} data-apex-chrome-panel>
148	      <AnimatePresence>
149	        {!previewActive && !modelingActive && (
150	          <motion.div
151	            ref={toolbarRef}
152	            className={styles.toolbar}
153	            initial={{ opacity: 0, x: -20 }}
154	            animate={{ opacity: 1, x: 0 }}
155	            // Vers Modélisation : ce panneau doit avoir fini de disparaître AVANT que le morph du
156	            // panneau catégories/pilule ne commence à se déformer (cf. ELEMENTS_FADE_MS, le temps
157	            // mort au tout début de modelingPathAt) — sa propre durée de sortie doit donc
158	            // correspondre exactement à ce délai, plus court que la transition générique (0.9s)
159	            // utilisée pour les autres sorties (ex. vers Dev).
160	            exit={{
161	              opacity: 0,
162	              x: -20,
163	              transition: {
164	                duration: modelingActive ? ELEMENTS_FADE_MS / 1000 : 0.9,
165	                ease: modelingActive ? 'easeInOut' : 'linear',
166	              },
167	            }}
168	            transition={{
169	              opacity: { duration: 0.9, ease: 'linear' },
170	              x: { duration: 0.9, ease: 'easeInOut' },
171	            }}
172	          >
173	        <div className={styles.content}>
174	          {models.length === 0 ? (
175	            <motion.div 
176	              initial={{ opacity: 0 }} 
177	              animate={{ opacity: 1 }} 
178	              exit={{ opacity: 0 }} 
179	              className={styles.emptyText}
180	            >
181	              Aucun modèle sur le plateau
182	            </motion.div>
183	          ) : (
184	            <ul className={styles.treeList}>
185	              <AnimatePresence>
186	                {models.map((model) => {
187	                  const isSelected = selectedModelNames.has(model.name);
188	                  const isExpanded = !!expandedModels[model.name];
189	                  return (
190	                    <motion.li 
191	                      key={model.id} 
192	                      className={styles.treeNode}
193	                      initial={{ opacity: 0, height: 0, scale: 0.9 }}
194	                      animate={{ opacity: 1, height: 'auto', scale: 1 }}
195	                      exit={{ opacity: 0, height: 0, scale: 0.9, marginBottom: 0 }}
196	                      transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }}
197	                    >
198	                      <div 
199	                        className={`${styles.nodeRow} ${isSelected ? styles.selectedNode : ''}`}
200	                        onClick={(e) => {
201	                          setSelectedModelName(model.name);
202	                          window.dispatchEvent(new CustomEvent('apex-select-model', {
203	                            detail: { name: model.name, additive: e.ctrlKey || e.metaKey }
204	                          }));
205	                        }}
206	                      >
207	                        <button 
208	                          className="bg-transparent border-none cursor-pointer p-0 flex items-center justify-center text-zinc-400 hover:text-white transition-colors"
209	                          onClick={(e) => toggleExpand(model.name, e)}
210	                        >
211	                          <ChevronRight 
212	                            size={14} 
213	                            className={`transition-transform duration-200 ${isExpanded ? 'rotate-90' : ''}`} 
214	                          />
215	                        </button>
216	                        <Box size={14} className="text-[#00f0ff] ml-1" />
217	                        <span className={styles.nodeName}>{model.name}</span>
218	                      </div>
219	                      <AnimatePresence>
220	                        {isExpanded && model.children && model.children.length > 0 && (
221	                          <motion.ul 
222	                            className={styles.childList}
223	                            initial={{ opacity: 0, height: 0 }}
224	                            animate={{ opacity: 1, height: 'auto' }}
225	                            exit={{ opacity: 0, height: 0 }}
226	                            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
227	                          >
228	                            {model.children.map(child => (
229	                              <li key={child.id} className={styles.childRow}>
230	                                <span 
231	                                  className="w-2.5 h-2.5 rounded-full shrink-0 mr-1.5 shadow-sm" 
232	                                  style={{ backgroundColor: child.color }} 
233	                                />
234	                                <span className={styles.childName}>{child.name}</span>
235	                              </li>
236	                            ))}
237	                          </motion.ul>
238	                        )}
239	                      </AnimatePresence>
240	                    </motion.li>
241	                  );
242	                })}
243	              </AnimatePresence>
244	            </ul>
245	          )}
246	        </div>
247	          </motion.div>
248	        )}
249	      </AnimatePresence>
250	    </div>
251	  );
252	};

