.fusionTitleContainer {
  position: fixed;
  left: 200px;
  top: 20px;
  width: 195px;
  height: 48px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 14px;
  z-index: 1001;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px 0 12px;
  isolation: isolate;
  transition: width 0.3s cubic-bezier(0.16, 1, 0.3, 1);

  &.expandedWidthTwo {
    width: 402px;
  }

  &.expandedWidthThree {
    width: 609px;
  }

  &.expandedWidthFour {
    width: 816px;
  }

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }

