1	"use client";
2	
3	import React, { useEffect, useRef, useState } from 'react';
4	import { Sidebar } from '@/components/Sidebar';
5	import { FileSidebar } from '@/components/FileSidebar';
6	import { SliceSidebar } from '@/components/SliceSidebar';
7	import { CategoriesSidebar } from '@/components/CategoriesSidebar';
8	import { PrinterConfigSidebar } from '@/components/PrinterConfigSidebar';
9	import { AxisSidebar } from '@/components/AxisSidebar';
10	import { ModelingSidebar } from '@/components/ModelingSidebar';
11	import { TopRightMenu } from '@/components/TopRightMenu';
12	import { ModelStatusBox } from '@/components/ModelStatusBox';
13	import { ModelHoverTooltip } from '@/components/ModelHoverTooltip';
14	import { TextureEditorModal } from '@/components/TextureEditorModal';
15	import { SliceModal } from '@/components/SliceModal';
16	import { SlicingProgressModal } from '@/components/SlicingProgressModal';
17	import { ViewCube } from '@/components/ViewCube';
18	import { Viewport3D } from '@/components/Viewport3D';
19	import { SpaceTransitionOverlay } from '@/components/SpaceTransitionOverlay';
20	import { ParamsPanel } from '@/components/ParamsPanel';
21	import { GCodePreview } from '@/components/GCodePreview';
22	import { GCodePreviewBar } from '@/components/GCodePreviewBar';
23	import { GCodeSpeedSelector } from '@/components/GCodeSpeedSelector';
24	import { GCodeLineTypeLegend } from '@/components/GCodeLineTypeLegend';
25	import { GCodeInfoPanel } from '@/components/GCodeInfoPanel';
26	import { GCodeConversionCard } from '@/components/GCodeConversionCard';
27	import { useGCodePreview } from '@/hooks/use-gcode-preview';
28	import { useAnimate, motion, AnimatePresence } from 'framer-motion';
29	import { Box } from 'lucide-react';
30	import { showSuccess } from '@/utils/toast';
31	
32	interface ModelStatus {
33	  name: string;
34	  dimensions: { x: number; y: number; z: number } | null;
35	}
36	
37	const Index = () => {
38	  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer' | 'params'>('3d-view');
39	  const [activeCategory, setActiveCategory] = useState<string | null>(null);
40	  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
41	  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
42	  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
43	  const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
44	  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
45	  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
46	  const [isPreviewActive, setIsPreviewActive] = useState(false);
47	  const isPreviewActiveRef = useRef(isPreviewActive);
48	  isPreviewActiveRef.current = isPreviewActive;
49	  // Logique de l'espace Prévisualisation (chargement/lecture G-code) : appelée ici (et non dans
50	  // GCodePreview) car sa barre de lecture (GCodePreviewBar) partage la rangée du bas avec la
51	  // pastille de statut du plateau, ce qui demande que les deux soient des enfants directs du même
52	  // conteneur flex plutôt que des composants positionnés indépendamment.
53	  const gcodePreview = useGCodePreview(isPreviewActive);
54	  // Le temps que ModelingSidebar déforme sa propre silhouette entre la forme de la pilule/des deux
55	  // panneaux de Prévisualisation et sa forme normale — cf. le commentaire sur `onTabChange` plus
56	  // bas et le prop `morph` de ModelingSidebar. `null` = pas de morph en cours ; sinon, `direction`
57	  // indique le sens ('enter' : la pilule/Prévisualisation devient le panneau Modélisation, 'exit' :
58	  // l'inverse) et `fromPreview` l'état de Prévisualisation à l'autre bout du morph (pilule ou
59	  // panneaux Preview) — figé à l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis
60	  // isPreviewActive : Sidebar mute ce dernier dans le même geste, avant qu'on ait la chance de lire
61	  // sa valeur de départ. Contrairement à l'ancienne approche (deux calques à synchroniser — un
62	  // verre animé séparé, puis le vrai panneau), c'est ICI le même élément, déjà affiché avec son
63	  // contenu réel, qui change de forme : plus de raccord entre deux éléments distincts, donc plus
64	  // de risque de clignotement à la jonction.
65	  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
66	  // Vrai dès le CLIC vers Modélisation (cf. l'écouteur d'apex-entering-modeling plus bas), jamais
67	  // seulement à `onCovered` (~900ms plus tard, une fois le rideau refermé) : le fondu-glissement du
68	  // panneau du bas de Prévisualisation doit être visible EN TRANSPARENCE À TRAVERS le rideau qui
69	  // monte, pas caché derrière lui — contrairement au vrai changement d'onglet (`onTabChange`), qui
70	  // lui reste cadencé par `onCovered`. Redevient faux une fois le morph 'enter' effectivement lancé
71	  // (le panneau du bas a alors largement eu le temps de finir sa disparition, 260ms contre les
72	  // ~900ms d'attente du rideau).
73	  const [leavingToModeling, setLeavingToModeling] = useState(false);
74	  const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
75	  const prevPreviewActiveRef = useRef(isPreviewActive);
76	
77	  // Au changement d'espace, la barre d'aide (TopRightMenu) passe par le coin bas gauche, là où
78	  // se trouve la barre de statut : celle-ci se rentre sous le bord de l'écran juste avant
79	  // (0,2 → 0,45 s ; la barre d'aide démarre à 0,495 s) et ressort une fois la barre d'aide
80	  // arrivée (1,1 s), pour ne pas se faire recouvrir.
81	  useEffect(() => {
82	    if (prevPreviewActiveRef.current === isPreviewActive) return;
83	    prevPreviewActiveRef.current = isPreviewActive;
84	    if (!statusBarRef.current) return;
85	    animateStatusBar(
86	      statusBarRef.current,
87	      { y: [0, 0, 80, 80, 0] },
88	      { duration: 1.4, times: [0, 0.2 / 1.4, 0.45 / 1.4, 1.1 / 1.4, 1], ease: [0.25, 1, 0.5, 1] },
89	    );
90	  }, [isPreviewActive, animateStatusBar, statusBarRef]);
91	
92	  /** L'onglet « Modélisation » de la Sidebar porte la valeur 'settings'. */
93	  const isModeling = activeTab === 'settings';
94	  // Espace Paramètres : le Viewport3D (et tout le reste du chrome sauf la barre d'onglets
95	  // Sidebar et la barre fichier/son FileSidebar) est entièrement démonté, pas seulement masqué —
96	  // aucune scène Babylon.js ne doit tourner en fond pendant que cet espace est affiché.
97	  const isParams = activeTab === 'params';
98	
99	  // Une fois CategoriesSidebar (et son panneau du bas) effectivement démontée par le passage en
100	  // Modélisation, `leavingToModeling` peut redescendre : il n'a plus d'effet visuel à cet instant
101	  // (le fondu est terminé depuis longtemps), mais doit être prêt (`false`) pour un futur cycle.
102	  useEffect(() => {
103	    if (isModeling) setLeavingToModeling(false);
104	  }, [isModeling]);
105	
106	  // Vrai du début d'un morph de sortie de Modélisation jusqu'au commit qui le termine, où
107	  // CategoriesSidebar est remontée et le lit (une seule fois, à son montage). Remis à `false` juste
108	  // après, une fois ce montage passé.
109	  const [arrivingFromModeling, setArrivingFromModeling] = useState(false);
110	  useEffect(() => {
111	    if (!modelingMorph) setArrivingFromModeling(false);
112	  }, [modelingMorph]);
113	
114	  React.useEffect(() => {
115	    const handleModelSelected = (event: CustomEvent<{
116	      name: string | null;
117	      dimensions?: { x: number; y: number; z: number };
118	    }>) => {
119	      if (!event.detail?.name) {
120	        setModelStatus(null);
121	        return;
122	      }
123	
124	      setModelStatus({
125	        name: event.detail.name,
126	        dimensions: event.detail.dimensions ?? null,
127	      });
128	    };
129	
130	    const handleModelImported = (event: CustomEvent<File>) => {
131	      if (event.detail?.name) {
132	        setModelStatus({ name: event.detail.name, dimensions: null });
133	      }
134	    };
135	
136	    const handlePreviewToggled = (event: CustomEvent<{ active: boolean }>) => {
137	      setIsPreviewActive(!!event.detail?.active);
138	    };
139	
140	    // Dispatché par Sidebar.tsx (handleTopTabClick) au tout début du clic vers Modélisation, avant
141	    // même que le rideau plein écran ne commence à monter — cf. le commentaire sur
142	    // `leavingToModeling` plus haut.
143	    const handleEnteringModeling = () => setLeavingToModeling(true);
144	
145	    window.addEventListener('apex-mesh-selected', handleModelSelected as EventListener);
146	    window.addEventListener('apex-import-model', handleModelImported as EventListener);
147	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
148	    window.addEventListener('apex-entering-modeling', handleEnteringModeling);
149	
150	    return () => {
151	      window.removeEventListener('apex-mesh-selected', handleModelSelected as EventListener);
152	      window.removeEventListener('apex-import-model', handleModelImported as EventListener);
153	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
154	      window.removeEventListener('apex-entering-modeling', handleEnteringModeling);
155	    };
156	  }, []);
157	
158	  const handleSlice = () => {
159	    window.dispatchEvent(new CustomEvent('apex-request-slice-models'));
160	    setIsSliceModalOpen(true);
161	  };
162	
163	  const handleConfirmSlice = () => {
164	    window.dispatchEvent(new CustomEvent('apex-slice-all-models'));
165	    setIsSliceModalOpen(false);
166	    setIsSlicingProgressOpen(true);
167	  };
168	
169	  const handleSlicingFinished = () => {
170	    setIsSlicingProgressOpen(false);
171	    showSuccess("Slicing plate completed successfully!");
172	  };
173	
174	  const handleOpenModel = () => {
175	    showSuccess("Select an STL or GLB file to add a model.");
176	  };
177	
178	  const handleSaveProject = () => {
179	    showSuccess("Project saved successfully.");
180	  };
181	
182	  return (
183	    <div
184	      className="flex flex-col h-screen w-screen overflow-hidden select-none relative"
185	      style={{ backgroundColor: '#2a2d34' }}
186	    >
187	      <FileSidebar 
188	        onOpenModel={handleOpenModel}
189	        onSaveProject={handleSaveProject}
190	        onOpenSettings={() => setActiveTab('settings')}
191	        onOpenPrinterConfig={() => {
192	          setIsPrinterConfigOpen(!isPrinterConfigOpen);
193	          setActiveCategory(null);
194	        }}
195	        selectedPrinter={selectedPrinter}
196	        selectedFilament={selectedFilament}
197	      />
198	
199	      {!isParams && (
200	        <>
201	          <ModelStatusBox />
202	          <ModelHoverTooltip />
203	          <TextureEditorModal />
204	          <SliceModal
205	            isOpen={isSliceModalOpen}
206	            onClose={() => setIsSliceModalOpen(false)}
207	            onConfirm={handleConfirmSlice}
208	          />
209	          <SlicingProgressModal
210	            isOpen={isSlicingProgressOpen}
211	            onClose={() => setIsSlicingProgressOpen(false)}
212	            onFinished={handleSlicingFinished}
213	          />
214	        </>
215	      )}
216	
217	      <Sidebar
218	        activeTab={activeTab}
219	        onTabChange={(tab, toPreview) => {
220	          // Passage vers ou hors de Modélisation : le rideau plein écran (déjà déclenché par
221	          // Sidebar avant cet appel, cf. playSpaceTransition) masque le changement de `main`,
222	          // pendant lequel ModelingSidebar (montée en permanence tant que isModeling ||
223	          // modelingMorph) joue le morph — cf. son prop `morph`.
224	          if (tab === 'settings' && !isModeling) {
225	            // L'état de départ (Préparation ou Prévisualisation) est lu MAINTENANT depuis
226	            // isPreviewActiveRef, avant que Sidebar ne le fasse passer à jour dans ce même geste.
227	            // Les éléments sans place en Modélisation ont déjà disparu depuis le clic
228	            // (apex-entering-modeling, ~900ms plus tôt) : la déformation peut commencer tout de
229	            // suite, dans le même commit que la bascule CategoriesSidebar → ModelingSidebar.
230	            setModelingMorph({ direction: 'enter', fromPreview: isPreviewActiveRef.current });
231	          } else if (tab !== 'settings' && isModeling) {
232	            // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
233	            // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui
234	            // passe `toPreview: true`) — la destination ne peut donc pas se lire depuis `tab` seul.
235	            setModelingMorph({ direction: 'exit', fromPreview: !!toPreview });
236	            setArrivingFromModeling(true);
237	          }
238	          setActiveTab(tab === 'box' ? '3d-view' : tab);
239	          setIsPrinterConfigOpen(false);
240	          if (tab === 'params') {
241	            setIsSliceModalOpen(false);
242	            setIsSlicingProgressOpen(false);
243	          }
244	        }}
245	        onOpenModel={handleOpenModel}
246	      />
247	
248	      {/* Espace Paramètres : tout le chrome lié au plateau 3D (viewport compris) se
249	          fondu-glisse en une fois plutôt que de disparaître d'un coup — seules la barre
250	          d'onglets (Sidebar) et la barre fichier/son (FileSidebar) restent visibles. Rendu
251	          conditionnel simple pour le Viewport3D (jamais monté en Paramètres, cf. CLAUDE.md sur
252	          Viewport3D) ; AnimatePresence porte uniquement la sortie/entrée visuelle de ce bloc. */}
253	      <AnimatePresence>
254	        {!isParams && (
255	          <motion.div
256	            key="apex-3d-chrome"
257	            initial={{ opacity: 0, y: 24 }}
258	            animate={{ opacity: 1, y: 0 }}
259	            exit={{ opacity: 0, y: 24 }}
260	            transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }}
261	          >
262	            <TopRightMenu />
263	            <AxisSidebar />
264	            <ViewCube />
265	
266	            {/* Les panneaux slicer et le panneau modélisation s'excluent mutuellement. La bascule se fait
267	                TOUJOURS dans un seul commit, par un rendu conditionnel simple — jamais via
268	                AnimatePresence, qui retarde le démontage de l'ancien côté (et en mode 'wait', le
269	                montage du nouveau) d'au moins une tâche, donc d'au moins une frame peinte. Toute
270	                l'animation visible est portée ailleurs : la déformation par ModelingSidebar (prop
271	                `morph`), les fondus par `animate` dès le clic. */}
272	            {isModeling || modelingMorph?.direction === 'exit' ? (
273	              <ModelingSidebar
274	                morph={
275	                  modelingMorph
276	                    ? { ...modelingMorph, onDone: () => setModelingMorph(null) }
277	                    : undefined
278	                }
279	              />
280	            ) : (
281	                <>
282	                  <CategoriesSidebar
283	                    activeCategory={activeCategory}
284	                    onSelectCategory={(cat) => {
285	                      setActiveCategory(cat);
286	                      if (cat) setIsPrinterConfigOpen(false);
287	                    }}
288	                    // Remonté à la fin d'un morph de sortie de Modélisation : ce composant doit apparaître
289	                    // directement dans la forme que ModelingSidebar vient de prendre (pilule ou panneaux
290	                    // de Prévisualisation), sans rejouer d'entrée ni de mitose. Ces deux props ne sont lues
291	                    // qu'au montage (figées en interne).
292	                    initialPreviewActive={isPreviewActive}
293	                    arrivingFromModeling={arrivingFromModeling}
